"""Profile guard under model mismatch: fires generated by forward models other than the inversion model.

Inversion model: constant, homogeneous forcing with known ignition and bearing, Anderson law fixed (s = 1),
with a log-normal prior on s (SD 0.1), or with s free; position error model E2 (sigma/D_h = 0.03,
ell/D_h = 0.1), as in graded_benchmark.py. Generators:
  constant  the inversion model itself (control);
  ramp      spatially uniform wind rising linearly from 0.85 to 1.15 times its mean over the record;
  gust      log-wind an Ornstein-Uhlenbeck process (SD 0.2, correlation time 0.1 of the record);
  veer      wind bearing oscillating by +-15 degrees (one cycle over the record);
  hetero    no-wind spread rate R0 a log-normal random field (CV 0.3, correlation length 150 m)
            under constant wind;
  mtt_uniform  uniform fuel computed with the same travel-time solver (control for 'hetero').
Fronts under time-varying homogeneous forcing are computed exactly from Huygens' principle: the
support function of the burned region is the time integral of the wavelet support functions.
Fronts in heterogeneous fuel are minimum-travel-time solutions on a 10-m grid with a 176-direction
stencil, each edge weighted by the ray speed of the elliptical wavelet and the harmonic mean of the
local spread-rate factors; 'mtt_uniform' applies the same solver to uniform fuel as a control for
solver error. Both use winds of 2-5 m/s, for which the solver error is small (RMS 0.7-3 m). The true wind is the time-mean wind over the record. For each fire we record
the guard statistic (30% displacement, converged refits), the 95% profile interval and its coverage,
and the residual lag-1 autocorrelation statistic of misspecification_checks.py.
Output: output/mismatch_scenarios.json, output/mismatch_cases.csv
"""
import json
import os
import sys
from math import gcd

import numpy as np
from scipy.interpolate import RegularGridInterpolator
from scipy.sparse import coo_matrix
from scipy.sparse.csgraph import dijkstra

import pyrofield_reduced as m
from benchmark_tables import decide
from graded_benchmark import D, HI, LO, cp, fit, profile_cost, profile_interval

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, "output")
K = 72
PSI = np.linspace(0.0, 2.0 * np.pi, K, endpoint=False)
FRAC = np.array([0.25, 0.5, 0.75, 1.0])
THETA = np.linspace(0.0, 2.0 * np.pi, 1440, endpoint=False)
NT = 400


def wavelet_support(theta, Rh, L, thw):
    a, b, c = m.ellipse_axes(Rh, L)
    d = theta - thw
    return c * np.cos(d) + np.sqrt((a * np.cos(d)) ** 2 + (b * np.sin(d)) ** 2)


def radii_from_support(h):
    dth = THETA[1] - THETA[0]
    dh = (np.roll(h, -1) - np.roll(h, 1)) / (2 * dth)
    x = h * np.cos(THETA) - dh * np.sin(THETA)
    y = h * np.sin(THETA) + dh * np.cos(THETA)
    ang = np.mod(np.arctan2(y, x), 2 * np.pi)
    o = np.argsort(ang)
    return np.interp(PSI, ang[o], np.hypot(x, y)[o], period=2 * np.pi)


def fronts_time_varying(R0, s, U_tau, th_tau, T):
    """Exact fronts at FRAC * T for spatially uniform forcing U(tau), theta(tau) sampled on NT+1 points."""
    tau = np.linspace(0.0, T, NT + 1)
    F = np.array([wavelet_support(THETA, m.head_rate(R0, u), m.L_anderson(u, s), th) for u, th in zip(U_tau, th_tau)])
    H = np.concatenate([np.zeros((1, THETA.size)), np.cumsum(0.5 * (F[1:] + F[:-1]) * (tau[1] - tau[0]), axis=0)])
    return np.concatenate([radii_from_support(H[int(round(f * NT))]) for f in FRAC])


GRID_X = np.arange(-400.0, 1600.0 + 1e-9, 10.0)
GRID_Y = np.arange(-650.0, 650.0 + 1e-9, 10.0)
STENCIL = [(i, j) for i in range(-8, 9) for j in range(-8, 9) if (i, j) != (0, 0) and gcd(abs(i), abs(j)) == 1]


def random_field(rng, sd=0.3, ell=150.0):
    ny, nx = GRID_Y.size, GRID_X.size
    w = rng.standard_normal((ny, nx))
    ky = np.fft.fftfreq(ny, d=10.0) * 2 * np.pi
    kx = np.fft.fftfreq(nx, d=10.0) * 2 * np.pi
    k2 = ky[:, None] ** 2 + kx[None, :] ** 2
    g = np.real(np.fft.ifft2(np.fft.fft2(w) * np.exp(-k2 * ell ** 2 / 4.0)))
    g = (g - g.mean()) / g.std() * sd
    return np.exp(g - sd ** 2 / 2.0)


def fronts_heterogeneous(R0, U, s, T, field):
    """Minimum-travel-time fronts at FRAC * T; field multiplies R0 (mean one)."""
    Rh = m.head_rate(R0, U)
    L = m.L_anderson(U, s)
    a, _, _ = m.ellipse_axes(Rh, L)
    e = np.sqrt(1 - 1 / L ** 2)
    ny, nx = field.shape
    idx = np.arange(ny * nx).reshape(ny, nx)
    rows, cols, wts = [], [], []
    for di, dj in STENCIL:
        y0, y1 = max(0, -dj), min(ny, ny - dj)
        x0, x1 = max(0, -di), min(nx, nx - di)
        src = idx[y0:y1, x0:x1].ravel()
        dst = idx[y0 + dj:y1 + dj, x0 + di:x1 + di].ravel()
        fs = field[y0:y1, x0:x1].ravel()
        fd = field[y0 + dj:y1 + dj, x0 + di:x1 + di].ravel()
        phi = np.arctan2(dj, di)
        v = a * (1 - e ** 2) / (1 - e * np.cos(phi))
        length = 10.0 * np.hypot(di, dj)
        rows.append(src)
        cols.append(dst)
        wts.append(length / (v * 2 * fs * fd / (fs + fd)))
    G = coo_matrix((np.concatenate(wts), (np.concatenate(rows), np.concatenate(cols))), shape=(ny * nx, ny * nx)).tocsr()
    ign = idx[np.argmin(np.abs(GRID_Y)), np.argmin(np.abs(GRID_X))]
    Tarr = dijkstra(G, directed=True, indices=ign).reshape(ny, nx)
    interp = RegularGridInterpolator((GRID_Y, GRID_X), Tarr, bounds_error=False, fill_value=np.inf)
    rr = np.arange(0.0, 1900.0, 2.0)
    out = []
    for f in FRAC:
        t = f * T
        r_t = []
        for p in PSI:
            Tr = interp(np.c_[rr * np.sin(p), rr * np.cos(p)])
            k = int(np.argmax(Tr > t))
            r_t.append(rr[k - 1] + (t - Tr[k - 1]) / (Tr[k] - Tr[k - 1]) * (rr[k] - rr[k - 1]) if k > 0 else 0.0)
        out.append(np.array(r_t))
    return np.concatenate(out)


class MismatchFire:
    def __init__(self, y, times, Rh_ref, L_ref, sigma_s):
        self.sigma_s = sigma_s
        self.op = m.BoundaryOperator(times, sigma=0.03 * D, corr_length=0.1 * D, Rh_ref=Rh_ref, L_ref=L_ref)
        self.y = y

    def resid(self, p, data=None):
        data = self.y if data is None else data
        U = np.exp(p[1])
        r = self.op.whiten(self.op(m.head_rate(np.exp(p[0]), U), m.L_anderson(U, np.exp(p[2]))) - data)
        return np.append(r, p[2] / self.sigma_s if self.sigma_s > 0 else 0.0)


MODES = {"fixed": 0.0, "prior": 0.1, "free": 1e6}


def make_fire(gen, mode, rng):
    R0 = rng.uniform(0.06, 0.16)
    U0 = rng.uniform(2.0, 5.0) if gen in ("hetero", "mtt_uniform") else rng.uniform(2.0, 7.0)
    s = 1.0 if mode == "fixed" else float(np.exp(rng.normal(0.0, 0.1)))
    Rh0, L0 = m.head_rate(R0, U0), m.L_anderson(U0, s)
    T = D / Rh0
    tau = np.linspace(0.0, T, NT + 1)
    th = np.zeros_like(tau)
    if gen == "constant":
        U = np.full_like(tau, U0)
    elif gen == "ramp":
        U = U0 * (0.85 + 0.30 * tau / T)
    elif gen == "gust":
        rho = np.exp(-(tau[1] - tau[0]) / (0.1 * T))
        x = np.empty_like(tau)
        x[0] = rng.normal(0.0, 0.2)
        for k in range(1, tau.size):
            x[k] = rho * x[k - 1] + np.sqrt(1 - rho ** 2) * rng.normal(0.0, 0.2)
        U = U0 * np.exp(x - x.mean())
    elif gen == "veer":
        U = np.full_like(tau, U0)
        th = np.deg2rad(15.0) * np.sin(2 * np.pi * tau / T)
    if gen in ("hetero", "mtt_uniform"):
        U_true = U0
        field = random_field(rng) if gen == "hetero" else np.ones((GRID_Y.size, GRID_X.size))
        clean = fronts_heterogeneous(R0, U0, s, T, field)
    else:
        U_true = float(np.trapezoid(U, tau) / T) if hasattr(np, "trapezoid") else float(np.trapz(U, tau) / T)
        clean = fronts_time_varying(R0, s, U, th, T)
    times = T * FRAC
    f = MismatchFire(None, times, Rh0, L0, MODES[mode])
    f.y = clean + f.op.sample_noise(rng)
    f.true_logU = np.log(U_true)
    return f


def residual_z(f, p):
    r = f.resid(p)[:-1].reshape(len(FRAC), K)
    r1 = [np.sum((ri - ri.mean()) * (np.roll(ri, 1) - ri.mean())) / np.sum((ri - ri.mean()) ** 2) for ri in r]
    return float(np.mean(r1) * np.sqrt(len(FRAC) * K))


def validate():
    """Generators against the exact homogeneous ellipse."""
    R0, U0 = 0.1, 4.0
    Rh0, L0 = m.head_rate(R0, U0), m.L_anderson(U0)
    T = D / Rh0
    exact = np.concatenate([m.front_radius(Rh0, L0, f * T, PSI) for f in FRAC])
    tv = fronts_time_varying(R0, 1.0, np.full(NT + 1, U0), np.zeros(NT + 1), T)
    out = {"support_function_max_rel_err": float(np.max(np.abs(tv / exact - 1)))}
    for U in (2.0, 3.5, 5.0):
        Rh, L = m.head_rate(R0, U), m.L_anderson(U)
        Tu = D / Rh
        ex = np.concatenate([m.front_radius(Rh, L, f * Tu, PSI) for f in FRAC])
        het = fronts_heterogeneous(R0, U, 1.0, Tu, np.ones((GRID_Y.size, GRID_X.size)))
        out[f"travel_time_U{U}"] = {"rms_abs_err_m": float(np.sqrt(np.mean((het - ex) ** 2))), "max_abs_err_m": float(np.max(np.abs(het - ex)))}
    return out


def run_cell(gen, mode, n, seed):
    rng = np.random.default_rng(seed)
    rows = []
    for _ in range(n):
        f = make_fire(gen, mode, rng)
        p_hat, chi_min = fit(f, rng)
        sides, inc = [], False
        for sgn in (-1, 1):
            z = p_hat[1] + sgn * np.log(1.3)
            if LO[1] <= z <= HI[1]:
                c_, ab = profile_cost(f, p_hat, z)
                sides.append(c_ - chi_min)
                inc = inc or ab
            else:
                sides.append(np.inf)
                inc = True
        du = float(max(0.0, min(sides)))
        lo_z, hi_z = profile_interval(f, p_hat, chi_min)
        rows.append({"gen": gen, "mode": mode, "U_true": float(np.exp(f.true_logU)), "U_hat": float(np.exp(p_hat[1])),
                     "abs_err": float(abs(np.expm1(p_hat[1] - f.true_logU))), "DU_d30": du, "inc": bool(inc),
                     "determined": decide(du, inc) == "determined", "covers": bool(lo_z <= f.true_logU <= hi_z),
                     "ci_halfwidth_log": float(0.5 * (hi_z - lo_z)) if np.isfinite(hi_z - lo_z) else None,
                     "chi2_per_obs": float(chi_min / (len(FRAC) * K)), "resid_z": residual_z(f, p_hat)})
    return rows


def summarise(rows):
    n = len(rows)
    k_det = sum(r["determined"] for r in rows)
    k_cov = sum(r["covers"] for r in rows)
    k_flag = sum(r["resid_z"] > 2.33 for r in rows)
    det = [r for r in rows if r["determined"]]
    return {"n": n, "determined": [k_det, cp(k_det, n)], "coverage": [k_cov, cp(k_cov, n)],
            "residual_flagged": [k_flag, cp(k_flag, n)], "median_abs_err": float(np.median([r["abs_err"] for r in rows])),
            "p90_abs_err_determined": float(np.percentile([r["abs_err"] for r in det], 90)) if det else None,
            "determined_err_above_30pct": int(sum(r["abs_err"] > 0.3 for r in det)),
            "median_chi2_per_obs": float(np.median([r["chi2_per_obs"] for r in rows])),
            "median_resid_z": float(np.median([r["resid_z"] for r in rows]))}


def main():
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 60
    os.makedirs(OUT, exist_ok=True)
    out = {"validation": validate()}
    print("validation", out["validation"], flush=True)
    cells = [(g, md, n) for g in ("constant", "ramp", "gust", "veer", "mtt_uniform", "hetero") for md in ("fixed", "prior")]
    cells += [(g, "free", max(10, n // 2)) for g in ("ramp", "hetero")]
    allrows = []
    for i, (g, md, nn) in enumerate(cells):
        rows = run_cell(g, md, nn, 7000 + i)
        allrows += rows
        out[f"{g},{md}"] = summarise(rows)
        print(g, md, json.dumps(out[f"{g},{md}"]), flush=True)
    json.dump(out, open(os.path.join(OUT, "mismatch_scenarios.json"), "w"), indent=1)
    keys = list(allrows[0].keys())
    with open(os.path.join(OUT, "mismatch_cases.csv"), "w", encoding="utf-8") as fh:
        fh.write(",".join(keys) + "\n")
        for r in allrows:
            fh.write(",".join(str(r[k]) for k in keys) + "\n")


if __name__ == "__main__":
    main()
